fun main() {
    val hi = 300
    val lo = 44
    println((hi - lo).toLong())
    println((hi + lo).toString())
    val a: Byte = 5
    val bb: Byte = 3
    println((a + bb).toString())
    val d = 1.5
    println((d * hi).toInt())
    val u: UInt = 7u
    val v: UInt = 2u
    println((u - v).toString())
    val l = 9L
    println((l / hi).toInt())
}
